SELECT p.id, 'PROCESO CONVOCATORIA PARA LA CONFORMACIÓN DE LA TERNA DEL SEGUNDO REPRESENTANTE DEL ESTAMENTO CIENTÍFICO ANTE LA JUNTA DIRECTIVA', 'proceso-convocatoria-para-la-conformacion-de-la-terna-del-segundo-repr-20260914', 'Una vez finalizado el término establecido para la recepción de postulaciones y realizada la verificación de los requisitos y documentos aportados por los aspirantes, se determina que los siguientes profesionales cumplen las…', '<p>Una vez finalizado el término establecido para la recepción de postulaciones y realizada la verificación de los requisitos y documentos aportados por los aspirantes, se determina que los siguientes profesionales cumplen las condiciones establecidas en la convocatoria para participar en la reunión destinada a la conformación de la terna del segundo representante del estamento científico de la salud ante la Junta Directiva:</p>', 'noticia', 'publicada', 'E.S.E. Hospital San José del Guaviare', '2026-09-14 17:00:00', 0, 'esehospitalguaviare.gov.co/publicaciones/16'
