SELECT p.id, 'CONFORMACIÓN DE TERNA DEL PERSONAL PROFESIONAL DE LA SALUD PARA EL SEGUNDO REPRESENTANTE DEL ESTAMENTO CIENTÍFICO ANTE LA JUNTA DIRECTIVA', 'conformacion-de-terna-del-personal-profesional-de-la-salud-para-el-seg-20260910', 'La E.S.E. Hospital San José del Guaviare convoca a los profesionales de todas las disciplinas de la salud que ejerzan en el área de influencia de la E.S.E., interesados en postularse para integrar la terna que será presentada a…', '<p>La E.S.E. Hospital San José del Guaviare convoca a los profesionales de todas las disciplinas de la salud que ejerzan en el área de influencia de la E.S.E., interesados en postularse para integrar la terna que será presentada a la Secretaría de Salud Departamental del Guaviare para la selección del segundo representante del estamento científico ante la Junta Directiva.</p>', 'noticia', 'publicada', 'E.S.E. Hospital San José del Guaviare', '2026-09-10 17:00:00', 0, 'esehospitalguaviare.gov.co/publicaciones/16'
