SELECT p.id, 'Primer aviso convocatoria a posibles interesados', 'primer-aviso-convocatoria-a-posibles-interesados-20260907', 'Que la E.S.E. Hospital San José del Guaviare procedió a liquidar los salarios y prestaciones sociales a los cuales tiene derecho la ex servidora pública ESPERANZA URQUIJO NOVA Q.E.P.D. , y a la fecha no se ha presentado ninguna…', '<p>Que la E.S.E. Hospital San José del Guaviare procedió a liquidar los salarios y prestaciones sociales a los cuales tiene derecho la ex servidora pública <strong>ESPERANZA URQUIJO NOVA Q.E.P.D.</strong>, y a la fecha no se ha presentado ninguna persona a reclamar formalmente dichas acreencias.</p>', 'noticia', 'publicada', 'E.S.E. Hospital San José del Guaviare', '2026-09-07 17:00:00', 0, 'esehospitalguaviare.gov.co/publicaciones/16'
