SELECT p.id, 'Comunicado interno de resultados de las elecciones de los representantes de los servidores ante la Comisión de Personal de la E.S.E. Hospital San José del Guaviare, correspondiente al período 2026–2028.', 'comunicado-interno-de-resultados-de-las-elecciones-de-los-representant-20260319', 'El Área de Talento humano de la E.S.E. Hospital San José del Guaviare, en cumplimiento de lo establecido en la Resolución N° 0152 de 2026, "Por medio de la cual se convoca y se fija el procedimiento para la elección de los…', '<p>El Área de Talento humano de la E.S.E. Hospital San José del Guaviare, en cumplimiento de lo establecido en la Resolución N° 0152 de 2026, "Por medio de la cual se convoca y se fija el procedimiento para la elección de los representantes de los servidores ante la comisión de Personal de la E.S.E. Hospital San José del Guaviare". Se permite informar a todos los servidores publicos de la entidad que han sido designadas las siguientes funcionarias como jurados de votación para el proceso de elección de los representantes de los trabajadores ante la Comisión de Personal.</p>', 'noticia', 'publicada', 'E.S.E. Hospital San José del Guaviare', '2026-03-19 17:00:00', 0, 'esehospitalguaviare.gov.co/publicaciones/16'
