SELECT p.id, 'Publicación de la ampliacion del comunicado relacionado con la Convocatoria para la Postulación de Candidatos al Comité de Convivencia Laboral para el periodo (2025-2027)', 'publicacion-de-la-ampliacion-del-comunicado-relacionado-con-la-convoca-20251215', 'La E.S.E. Hospital San José del Guaviare informa que se ha expedido y publicado la del comunicado relacionado con la Convocatoria para la Postulación de Candidatos al Comité de Convivencia Laboral para el periodo 2025–2027. Con…', '<p>La E.S.E. Hospital San José del Guaviare informa que se ha expedido y publicado la del comunicado relacionado con la Convocatoria para la Postulación de Candidatos al Comité de Convivencia Laboral para el periodo 2025–2027. Con esta acción se continúa fortaleciendo las estrategias institucionales orientadas al bienestar laboral, la motivación y la calidad de vida en el trabajo. La administración agradece la participación de los servidores comprometidos con este proceso, reafirmando su interés en promover espacios de integración y desarrollo organizacional.</p>', 'noticia', 'publicada', 'E.S.E. Hospital San José del Guaviare', '2025-12-15 17:00:00', 0, 'esehospitalguaviare.gov.co/publicaciones/16'
