SELECT p.id, '¡Feliz Día de las Madres!', 'feliz-dia-de-las-madres-20250511', 'En el Día de las Madres, la ESE Hospital San José del Guaviare, en cabeza de su gerente, el Dr. Germán Amézquita Niño, rinde un homenaje especial a todas las madres que forman parte de nuestra comunidad: funcionarias, usuarias y…', '<p>En el Día de las Madres, la ESE Hospital San José del Guaviare, en cabeza de su gerente, el Dr. Germán Amézquita Niño, rinde un homenaje especial a todas las madres que forman parte de nuestra comunidad: funcionarias, usuarias y cuidadoras; mujeres que cada día inspiran con su amor, entrega y fortaleza.<br>Hoy celebramos su existencia y su papel fundamental en la construcción de una sociedad más humana, solidaria y llena de esperanza.<br>¡Feliz Día!<br>#TuSaludNuestroCompromiso<br>#LaSaludAvanza</p>
<p><a href="https://www.facebook.com/share/v/1EhAqGs7tB/" target="_blank" rel="noopener">Ver la publicación original en Facebook</a></p>', 'noticia', 'publicada', 'E.S.E. Hospital San José del Guaviare', '2025-05-11 17:00:00', 0, 'esehospitalguaviare.gov.co/publicaciones/16'
