SELECT p.id, 'Homenaje en vida a Gloria Gutiérrez Triana por sus 46 años de servicio', 'homenaje-en-vida-a-gloria-gutierrez-triana-por-sus-46-anos-de-servicio-20250501', 'Desde la ESE Hospital San José del Guaviare, en cabeza de su gerente, el Dr. Germán Amézquita Niño, y en el marco del #DíaInternacionalDelTrabajo , rendimos un homenaje especial a nuestra compañera Gloria Gutiérrez Triana, quien…', '<p>Desde la ESE Hospital San José del Guaviare, en cabeza de su gerente, el Dr. Germán Amézquita Niño, y en el marco del <strong>#DíaInternacionalDelTrabajo</strong>, rendimos un homenaje especial a nuestra compañera Gloria Gutiérrez Triana, quien dedicó <strong>46 años de su vida al servicio de la salud</strong> con amor, compromiso y vocación.<br>Su entrega como auxiliar en el área de la salud deja una huella imborrable en nuestra institución.<br>Gracias, Gloria, por toda una vida de servicio. Te deseamos muchos éxitos y bendiciones en esta nueva etapa de descanso y nuevos comienzos.<br>#TuSaludNuestroCompromiso<br>#LaSaludAvanza</p>
<p><a href="https://www.facebook.com/share/p/1EubBhBLRQ/" target="_blank" rel="noopener">Ver la publicación original en Facebook</a></p>', 'noticia', 'publicada', 'E.S.E. Hospital San José del Guaviare', '2025-05-01 17:00:00', 0, 'esehospitalguaviare.gov.co/publicaciones/16'
