SELECT p.id, 'Jornada de ecografías y consultas por cirugía general en Miraflores, Guaviare', 'jornada-de-ecografias-y-consultas-por-cirugia-general-en-miraflores-gu-20250430', '¡Éxito total en el municipio de Miraflores! Más de 440 personas participaron en la primera jornada de ecografías y consultas por cirugía general del año 2025, liderada por la ESE Hospital San José del Guaviare y realizada en el…', '<p>¡Éxito total en el municipio de Miraflores!<br>Más de 440 personas participaron en la primera jornada de ecografías y consultas por cirugía general del año 2025, liderada por la ESE Hospital San José del Guaviare y realizada en el Hospital Albert Schweitzer del municipio de Miraflores.<br>Gracias a esta iniciativa, nuestros usuarios accedieron a servicios especializados de manera oportuna, mejorando el acceso a la salud en zonas apartadas del departamento.<br>Agradecemos la articulación con la Nueva EPS y la Alcaldía del Municipio de Miraflores, Guaviare, por hacer parte de este esfuerzo conjunto en beneficio de la comunidad.<br>¡Seguimos avanzando por una salud más cercana, humana y con resultados para todos!<br>#TuSaludNuestroCompromiso<br>#LaSaludAvanza</p>
<p><a href="https://www.facebook.com/share/p/1EfNYwQKP7/" target="_blank" rel="noopener">Ver la publicación original en Facebook</a></p>', 'noticia', 'publicada', 'E.S.E. Hospital San José del Guaviare', '2025-04-30 17:00:00', 0, 'esehospitalguaviare.gov.co/publicaciones/16'
  FROM cms_paginas p WHERE p.slug = 'noticias' AND NOT EXISTS (SELECT 1 FROM cms_entradas e WHERE e.pagina_id = p.id AND e.slug = 'jornada-de-ecografias-y-consultas-por-cirugia-general-en-miraflores-gu-20250430');
SELECT p.id, 'Capacitación en Tamizaje Neonatal Visual', 'capacitacion-en-tamizaje-neonatal-visual-20250428', 'En la ESE Hospital San José del Guaviare seguimos fortaleciendo las competencias de nuestro talento humano en salud. Hoy se realizó una jornada de capacitación teórico-práctica en Tamizaje Neonatal Visual, dirigida a nuestro…', '<p>En la ESE Hospital San José del Guaviare seguimos fortaleciendo las competencias de nuestro talento humano en salud.<br>Hoy se realizó una jornada de capacitación teórico-práctica en Tamizaje Neonatal Visual, dirigida a nuestro personal médico, con el objetivo de optimizar la identificación temprana de alteraciones visuales en niñas y niños recién nacidos mediante el examen físico.<br>Esta actividad, enmarcada en la Ruta Materno Perinatal, hace parte de la implementación de la Resolución 207 de 2024, que adopta los lineamientos técnicos y operativos del Programa de Tamizaje Neonatal en Colombia.<br>La capacitación fue liderada por el Dr. Leonardo Almeida, optómetra de la Secretaría de Salud Departamental del Guaviare, a quien agradecemos su valioso apoyo y compromiso.<br>¡Seguimos trabajando por una atención integral, oportuna y de calidad para nuestras madres gestantes y recién nacidos!<br>#TuSaludNuestroCompromiso<br>#LaSaludAvanza</p>
<p><a href="https://www.facebook.com/share/p/1ASsXhpKzF/" target="_blank" rel="noopener">Ver la publicación original en Facebook</a></p>', 'noticia', 'publicada', 'E.S.E. Hospital San José del Guaviare', '2025-04-28 17:00:00', 0, 'esehospitalguaviare.gov.co/publicaciones/16'
  FROM cms_paginas p WHERE p.slug = 'noticias' AND NOT EXISTS (SELECT 1 FROM cms_entradas e WHERE e.pagina_id = p.id AND e.slug = 'capacitacion-en-tamizaje-neonatal-visual-20250428');
SELECT p.id, 'Día Mundial de la Seguridad y Salud en el Trabajo', 'dia-mundial-de-la-seguridad-y-salud-en-el-trabajo-20250428', 'En el marco del Día Mundial de la Seguridad y Salud en el Trabajo, la ESE Hospital San José del Guaviare reconoce la importancia de promover entornos laborales seguros y saludables para todos nuestros colaboradores…', '<p>En el marco del Día Mundial de la Seguridad y Salud en el Trabajo, la ESE Hospital San José del Guaviare reconoce la importancia de promover entornos laborales seguros y saludables para todos nuestros colaboradores.<br>#TuSaludNuestroCompromiso<br>#LaSaludAvanza</p>
