  FROM cms_paginas p WHERE p.slug = 'noticias' AND NOT EXISTS (SELECT 1 FROM cms_entradas e WHERE e.pagina_id = p.id AND e.slug = 'semana-de-vacunacion-en-las-americas-20250426');
SELECT p.id, 'Comprometidos con una atención en salud más eficiente y humana para el Guaviare', 'comprometidos-con-una-atencion-en-salud-mas-eficiente-y-humana-para-el-20250426', 'La ESE Hospital San José del Guaviare, comprometida con la salud del departamento, ha liderado un proceso de articulación con la red de prestadores de salud, incluyendo Esered Guaviare, Nueva Salud Integral y Nueva EPS, para…', '<p>La ESE Hospital San José del Guaviare, comprometida con la salud del departamento, ha liderado un proceso de articulación con la red de prestadores de salud, incluyendo Esered Guaviare, Nueva Salud Integral y Nueva EPS, para atender las quejas de la comunidad relacionadas con escasez de medicamentos, congestión en urgencias, demoras en remisiones y prolongados tiempos de hospitalización.<br>En colaboración con la Secretaría de Salud del Guaviare y la Secretaría de Salud Municipal de San José del Guaviare, se diseñó una ruta de atención que involucra a todos los actores del sistema, con el fin de mejorar la gestión, ofrecer atención oportuna y evitar la saturación en urgencias y hospitalización.<br>Seguimos trabajando con responsabilidad y compromiso para garantizar una atención en salud eficiente, humana y cercana a las necesidades de nuestros usuarios.<br>#TuSaludNuestroCompromiso<br>#LaSaludAvanza</p>
<p><a href="https://www.facebook.com/share/p/1AaeTvC57h/" target="_blank" rel="noopener">Ver la publicación original en Facebook</a></p>', 'noticia', 'publicada', 'E.S.E. Hospital San José del Guaviare', '2025-04-26 17:00:00', 0, 'esehospitalguaviare.gov.co/publicaciones/16'
  FROM cms_paginas p WHERE p.slug = 'noticias' AND NOT EXISTS (SELECT 1 FROM cms_entradas e WHERE e.pagina_id = p.id AND e.slug = 'comprometidos-con-una-atencion-en-salud-mas-eficiente-y-humana-para-el-20250426');
SELECT p.id, '¡Feliz Día del Niño!', 'feliz-dia-del-nino-20250426', 'En la ESE Hospital San José del Guaviare celebramos la alegría, inocencia y los sueños de nuestros niños. Hoy y siempre, trabajamos por su bienestar y felicidad. ¡Feliz Día del Niño! #TuSaludNuestroCompromiso #LaSaludAvanza', '<p>En la ESE Hospital San José del Guaviare celebramos la alegría, inocencia y los sueños de nuestros niños.<br>Hoy y siempre, trabajamos por su bienestar y felicidad.<br>¡Feliz Día del Niño!<br>#TuSaludNuestroCompromiso<br>#LaSaludAvanza</p>
