SELECT p.id, 'Salidas Ecológicas 2025', 'salidas-ecologicas-2025-20250425', 'Hoy dimos inicio a las Salidas Ecológicas 2025, una actividad del Plan de Bienestar Social e Incentivos de la ESE Hospital San José del Guaviare. Con gran cariño, esta primera salida rinde homenaje a nuestra compañera Gloria…', '<p>Hoy dimos inicio a las Salidas Ecológicas 2025, una actividad del Plan de Bienestar Social e Incentivos de la ESE Hospital San José del Guaviare.<br>Con gran cariño, esta primera salida rinde homenaje a nuestra compañera Gloria Gutiérrez Triana, quien culmina una vida de trabajo, compromiso y dedicación con nuestra institución y su familia.<br>Gloria se acoge a su pensión a partir de mayo de 2025, y por ello, hoy queremos expresarle nuestro agradecimiento y desearle muchos éxitos en esta nueva etapa.<br>Desde la ESE Hospital San José del Guaviare seguimos comprometidos con el bienestar de todos nuestros colaboradores, promoviendo espacios que fortalecen el compañerismo, la gratitud y la calidad de vida.<br>#TuSaludNuestroCompromiso<br>#LaSaludAvanza</p>
<p><a href="https://www.facebook.com/share/p/1ZVV5SxWdY/" target="_blank" rel="noopener">Ver la publicación original en Facebook</a></p>', 'noticia', 'publicada', 'E.S.E. Hospital San José del Guaviare', '2025-04-25 17:00:00', 0, 'esehospitalguaviare.gov.co/publicaciones/16'
  FROM cms_paginas p WHERE p.slug = 'noticias' AND NOT EXISTS (SELECT 1 FROM cms_entradas e WHERE e.pagina_id = p.id AND e.slug = 'salidas-ecologicas-2025-20250425');
SELECT p.id, 'Día Mundial contra la Malaria', 'dia-mundial-contra-la-malaria-20250425', '🦟 ¿Sabías que la malaria aún cobra la vida de más de 600 mil personas cada año? La mayoría de las víctimas son niños menores de 5 años. La buena noticia es que la malaria se puede prevenir y curar. 💪 Acudir al médico a tiempo…', '<p>🦟 ¿Sabías que la malaria aún cobra la vida de más de 600 mil personas cada año?<br>La mayoría de las víctimas son niños menores de 5 años. La buena noticia es que la malaria se puede prevenir y curar.<br>💪 Acudir al médico a tiempo puede salvar vidas.<br>#TuSaludNuestroCompromiso #LaSaludAvanza</p>
<p><a href="https://www.facebook.com/share/p/1KyekaQjva/" target="_blank" rel="noopener">Ver la publicación original en Facebook</a></p>', 'noticia', 'publicada', 'E.S.E. Hospital San José del Guaviare', '2025-04-25 17:00:00', 0, 'esehospitalguaviare.gov.co/publicaciones/16'
  FROM cms_paginas p WHERE p.slug = 'noticias' AND NOT EXISTS (SELECT 1 FROM cms_entradas e WHERE e.pagina_id = p.id AND e.slug = 'dia-mundial-contra-la-malaria-20250425');
SELECT p.id, 'Jornada de Ecografías y Consulta por Cirugía General en Miraflores', 'jornada-de-ecografias-y-consulta-por-cirugia-general-en-miraflores-20250422', '¡Atención Miraflores! La ESE Hospital San José del Guaviare extiende una cordial invitación a toda la comunidad del municipio de Miraflores, Guaviare, a participar en la Gran Jornada de Ecografías y consulta por cirugía general…', '<p>¡Atención Miraflores!<br>La ESE Hospital San José del Guaviare extiende una cordial invitación a toda la comunidad del municipio de Miraflores, Guaviare, a participar en la Gran Jornada de Ecografías y consulta por cirugía general, que se realizará los días <strong>26, 27 y 28 de abril de 2025</strong>, en el Hospital Albert Schweitzer, en horario de <strong>8:00 a.m. a 5:00 p.m.</strong><br>Esta jornada está dirigida a usuarios de la Nueva EPS que cuenten con orden médica, sin necesidad de autorización previa.<br>¡Aprovecha esta oportunidad para cuidar tu salud!<br>#TuSaludNuestroCompromiso #LaSaludAvanza</p>
<p><a href="https://www.facebook.com/share/p/1AWkV24GXy/" target="_blank" rel="noopener">Ver la publicación original en Facebook</a></p>', 'noticia', 'publicada', 'E.S.E. Hospital San José del Guaviare', '2025-04-22 17:00:00', 0, 'esehospitalguaviare.gov.co/publicaciones/16'
  FROM cms_paginas p WHERE p.slug = 'noticias' AND NOT EXISTS (SELECT 1 FROM cms_entradas e WHERE e.pagina_id = p.id AND e.slug = 'jornada-de-ecografias-y-consulta-por-cirugia-general-en-miraflores-20250422');
SELECT p.id, 'Comunicado N° 027 - Actualización fecha de elecciones COPASST', 'comunicado-n-027-actualizacion-fecha-de-elecciones-copasst-20250527', 'En cumplimiento con la convocatoria para la elección de los representantes de los empleados ante el Comité Paritario de Seguridad y Salud en el Trabajo (COPASST), informamos que la fecha de votación virtual ha sido modificada. La…', '<p>En cumplimiento con la convocatoria para la elección de los representantes de los empleados ante el Comité Paritario de Seguridad y Salud en el Trabajo (COPASST), informamos que la fecha de votación virtual ha sido modificada.<br>La votación se realizará el día 5 de junio de 2025, en horario de 8:00 a.m. a 4:00 p.m.</p>', 'noticia', 'publicada', 'E.S.E. Hospital San José del Guaviare', '2025-05-27 17:00:00', 0, 'esehospitalguaviare.gov.co/publicaciones/16'
