SELECT p.id, 'Comunicado Interno N° 026 - Candidatos COPASST', 'comunicado-interno-n-026-candidatos-copasst-20250526', 'En cumplimiento con la convocatoria para la elección de los representantes de los empleados ante el Comité Paritario de Seguridad y Salud en el Trabajo (COPASST), nos permitimos informar la lista oficial de los servidores…', '<p>En cumplimiento con la convocatoria para la elección de los representantes de los empleados ante el Comité Paritario de Seguridad y Salud en el Trabajo (COPASST), nos permitimos informar la lista oficial de los servidores públicos que se han postulado como candidatos para el periodo 2025-2027.</p>', 'noticia', 'publicada', 'E.S.E. Hospital San José del Guaviare', '2025-05-26 17:00:00', 0, 'esehospitalguaviare.gov.co/publicaciones/16'
