SELECT p.id, 'Fiebre Amarilla', 'fiebre-amarilla-20250416', 'La fiebre amarilla es una enfermedad grave transmitida por la picadura de mosquitos infectados. Sus síntomas pueden incluir fiebre alta, dolor de cabeza, vómito y en casos severos, complicaciones hepáticas. La mejor forma de…', '<p>La fiebre amarilla es una enfermedad grave transmitida por la picadura de mosquitos infectados. Sus síntomas pueden incluir fiebre alta, dolor de cabeza, vómito y en casos severos, complicaciones hepáticas.<br>La mejor forma de prevenirla es con la vacuna. Es segura, gratuita y protege de por vida.<br>Desde la E.S.E Hospital San José del Guaviare, invitamos a toda la comunidad a acercarse al punto de vacunación más cercano.<br>#TuSaludNuestroCompromiso<br>#LaSaludAvanza</p>
<p><a href="https://www.facebook.com/share/p/1BaQQgv9Ec/" target="_blank" rel="noopener">Ver la publicación original en Facebook</a></p>', 'noticia', 'publicada', 'E.S.E. Hospital San José del Guaviare', '2025-04-16 17:00:00', 0, 'esehospitalguaviare.gov.co/publicaciones/16'
  FROM cms_paginas p WHERE p.slug = 'noticias' AND NOT EXISTS (SELECT 1 FROM cms_entradas e WHERE e.pagina_id = p.id AND e.slug = 'fiebre-amarilla-20250416');
SELECT p.id, 'Gran jornada interinstitucional de salud - Caño Blanco II', 'gran-jornada-interinstitucional-de-salud-cano-blanco-ii-20250414', 'Desde la E.S.E Hospital San José del Guaviare agradecemos la participación en la jornada interinstitucional de salud realizada en la vereda Caño Blanco II. Trabajamos de la mano con la Gobernación de Guaviare, Secretaría de Salud…', '<p>Desde la E.S.E Hospital San José del Guaviare agradecemos la participación en la jornada interinstitucional de salud realizada en la vereda Caño Blanco II.<br>Trabajamos de la mano con la Gobernación de Guaviare, Secretaría de Salud Departamental y E.S.E Red de Servicios de Salud de Primer Nivel para acercar nuestros servicios a la comunidad.<br>Durante la jornada brindamos atención en medicina general, ginecología, pediatría, nutrición, radiología, odontología y psicología, reafirmando que tu salud es nuestro compromiso.<br>¡Seguimos llegando a donde más nos necesitan!<br>#TuSaludNuestroCompromiso<br>#LaSaludAvanza</p>
<p><a href="https://www.facebook.com/share/p/1ULu1oBDDX/" target="_blank" rel="noopener">Ver la publicación original en Facebook</a></p>', 'noticia', 'publicada', 'E.S.E. Hospital San José del Guaviare', '2025-04-14 17:00:00', 0, 'esehospitalguaviare.gov.co/publicaciones/16'
