SELECT p.id, 'Día Mundial de la Lucha contra la Enfermedad de Chagas', 'dia-mundial-de-la-lucha-contra-la-enfermedad-de-chagas-20250414', 'En el Día Mundial de la lucha contra la Enfermedad de Chagas, la E.S.E Hospital San José del Guaviare recuerda la importancia de la prevención, el diagnóstico temprano y el tratamiento oportuno. Protejamos nuestra salud y la de…', '<p>En el Día Mundial de la lucha contra la Enfermedad de Chagas, la E.S.E Hospital San José del Guaviare recuerda la importancia de la prevención, el diagnóstico temprano y el tratamiento oportuno.<br>Protejamos nuestra salud y la de nuestras familias.<br>¡La Chagas se puede prevenir!<br>#TuSaludNuestroCompromiso<br>#LaSaludAvanza</p>
