SELECT p.id, 'Acompañamiento a Servidores Prepensionados', 'acompanamiento-a-servidores-prepensionados-20250414', 'La E.S.E Hospital San José del Guaviare adelanta un proceso de acompañamiento humanizado para servidores públicos próximos a pensionarse. Este programa busca facilitar una transición laboral planificada y con bienestar…', '<p>La E.S.E Hospital San José del Guaviare adelanta un proceso de acompañamiento humanizado para servidores públicos próximos a pensionarse. Este programa busca facilitar una transición laboral planificada y con bienestar psicosocial, a través de encuentros mensuales que abordan temas clave como salud integral, bienestar emocional, salud financiera, relaciones sociales y proyectos de vida en la jubilación.<br>En el último encuentro se trataron hábitos saludables, alimentación balanceada y actividad física.<br>Esta iniciativa reafirma el compromiso de la E.S.E Hospital San José del Guaviare con el bienestar de quienes han servido a la salud pública.<br>#TuSaludNuestroCompromiso<br>#LaSaludAvanza</p>
<p><a href="https://www.facebook.com/share/p/167EKVqoYe/" target="_blank" rel="noopener">Ver la publicación original en Facebook</a></p>', 'noticia', 'publicada', 'E.S.E. Hospital San José del Guaviare', '2025-04-14 17:00:00', 0, 'esehospitalguaviare.gov.co/publicaciones/16'
  FROM cms_paginas p WHERE p.slug = 'noticias' AND NOT EXISTS (SELECT 1 FROM cms_entradas e WHERE e.pagina_id = p.id AND e.slug = 'acompanamiento-a-servidores-prepensionados-20250414');
SELECT p.id, 'Jornada de Ecografías - El Retorno', 'jornada-de-ecografias-el-retorno-20250411', '¡Atención Retorno! La E.S.E Hospital San José del Guaviare extiende una cordial invitación a toda la comunidad del municipio de El Retorno, Guaviare, a participar en la Gran Jornada de Ecografías este próximo 13 de abril de 2025…', '<p>¡Atención Retorno!<br>La E.S.E Hospital San José del Guaviare extiende una cordial invitación a toda la comunidad del municipio de El Retorno, Guaviare, a participar en la Gran Jornada de Ecografías este próximo 13 de abril de 2025, en el Hospital de Primer Nivel, en horario de 8:00 a.m. a 5:00 p.m.<br>Esta jornada está dirigida a usuarios de la Nueva EPS que cuenten con orden médica, sin necesidad de autorización previa.<br>¡Aprovecha esta oportunidad para cuidar tu salud!<br>#TuSaludNuestroCompromiso<br>#LaSaludAvanza</p>
