SELECT p.id, 'Jornada de Ecografías - Calamar', 'jornada-de-ecografias-calamar-20250411', '¡Atención Calamar! La E.S.E Hospital San José del Guaviare extiende una cordial invitación a toda la comunidad del municipio de Calamar, Guaviare, a participar en la Gran Jornada de Ecografías este próximo 12 de abril de 2025, en…', '<p>¡Atención Calamar!<br>La E.S.E Hospital San José del Guaviare extiende una cordial invitación a toda la comunidad del municipio de Calamar, Guaviare, a participar en la Gran Jornada de Ecografías este próximo 12 de abril de 2025, en el Hospital María Cristina Cobo, en horario de 8:00 a.m. a 5:00 p.m.<br>Esta jornada está dirigida a usuarios de la Nueva EPS que cuenten con orden médica, sin necesidad de autorización previa.<br>¡Aprovecha esta oportunidad para cuidar tu salud!<br>#TuSaludNuestroCompromiso<br>#LaSaludAvanza</p>
