SELECT p.id, 'Condolencias', 'condolencias-20250410', 'La E.S.E. Hospital San José del Guaviare, en cabeza de su gerente Germán Amézquita, lamenta profundamente el fallecimiento del señor Rober Estiven Duran Chávez, Q.E.P.D. Hijo de nuestra compañera Aleida Chávez Espinosa y hermano…', '<p>La E.S.E. Hospital San José del Guaviare, en cabeza de su gerente Germán Amézquita, lamenta profundamente el fallecimiento del señor Rober Estiven Duran Chávez, Q.E.P.D. Hijo de nuestra compañera Aleida Chávez Espinosa y hermano de nuestra compañera Alejandra Chávez Espinosa.<br>Expresamos nuestras más sinceras condolencias a toda su familia en este difícil momento.<br>Que su alma descanse en paz.</p>
<p><a href="https://www.facebook.com/share/p/1FTvPtn1yM/" target="_blank" rel="noopener">Ver la publicación original en Facebook</a></p>', 'noticia', 'publicada', 'E.S.E. Hospital San José del Guaviare', '2025-04-10 17:00:00', 0, 'esehospitalguaviare.gov.co/publicaciones/16'
