SELECT p.id, 'Día Mundial de la Salud', 'dia-mundial-de-la-salud-20250407', 'Día Mundial de la Salud Hoy recordamos que la salud comienza contigo. Cuida tu cuerpo, tu mente y tus hábitos. Desde la E.S.E Hospital San José del Guaviare, estamos contigo. #TuSaludEsNuestroCompromiso #LaSaludAvanza', '<p>Día Mundial de la Salud<br>Hoy recordamos que la salud comienza contigo.<br>Cuida tu cuerpo, tu mente y tus hábitos.<br>Desde la E.S.E Hospital San José del Guaviare, estamos contigo.<br>#TuSaludEsNuestroCompromiso<br>#LaSaludAvanza</p>
