  FROM cms_paginas p WHERE p.slug = 'noticias' AND NOT EXISTS (SELECT 1 FROM cms_entradas e WHERE e.pagina_id = p.id AND e.slug = 'dia-mundial-de-la-salud-20250407');
SELECT p.id, 'Comprometidos con el bienestar de nuestro equipo de salud', 'comprometidos-con-el-bienestar-de-nuestro-equipo-de-salud-20250403', 'En la E.S.E Hospital San José del Guaviare, trabajamos para fortalecer la salud ocupacional de nuestro talento humano. Por eso, junto a ARL SURA y el SG-SST, socializamos el Plan de Trabajo 2025, una hoja de ruta clave para la…', '<p>En la E.S.E Hospital San José del Guaviare, trabajamos para fortalecer la salud ocupacional de nuestro talento humano. Por eso, junto a ARL SURA y el SG-SST, socializamos el Plan de Trabajo 2025, una hoja de ruta clave para la prevención de riesgos laborales y la promoción de un entorno seguro y saludable.<br><br>La seguridad y el bienestar de nuestro equipo es nuestra prioridad. Seguimos avanzando con acciones que protejan a quienes cada día entregan su vocación al servicio de la comunidad.</p>
<p><a href="https://www.facebook.com/share/p/1VT2K7ka3G/" target="_blank" rel="noopener">Ver la publicación original en Facebook</a></p>', 'noticia', 'publicada', 'E.S.E. Hospital San José del Guaviare', '2025-04-03 17:00:00', 0, 'esehospitalguaviare.gov.co/publicaciones/16'
  FROM cms_paginas p WHERE p.slug = 'noticias' AND NOT EXISTS (SELECT 1 FROM cms_entradas e WHERE e.pagina_id = p.id AND e.slug = 'comprometidos-con-el-bienestar-de-nuestro-equipo-de-salud-20250403');
SELECT p.id, '¿Qué es un conflicto de interés?', 'que-es-un-conflicto-de-interes-20250402', 'En la E.S.E Hospital San José del Guaviare, trabajamos con principios de ética y claridad. Por eso, queremos contarte qué es un conflicto de interés, cómo actuar si identificas uno y cuáles son los canales para reportarlo. Un…', '<p>En la E.S.E Hospital San José del Guaviare, trabajamos con principios de ética y claridad. Por eso, queremos contarte qué es un conflicto de interés, cómo actuar si identificas uno y cuáles son los canales para reportarlo.<br><br>Un conflicto de interés ocurre cuando los intereses personales, familiares o profesionales pueden influir en la toma de decisiones dentro del hospital.<br><br><b>¿Qué hacer si identificas uno?</b><br>- Actúa con transparencia.<br>- Informa la situación a tiempo.<br>- Usa nuestros canales oficiales para reportarlo.<br><br>Tu confianza es clave para seguir construyendo un hospital transparente y al servicio de todos.</p>
<p><a href="https://www.facebook.com/share/v/16Qsqr7Lje/" target="_blank" rel="noopener">Ver la publicación original en Facebook</a></p>', 'noticia', 'publicada', 'E.S.E. Hospital San José del Guaviare', '2025-04-02 17:00:00', 0, 'esehospitalguaviare.gov.co/publicaciones/16'
  FROM cms_paginas p WHERE p.slug = 'noticias' AND NOT EXISTS (SELECT 1 FROM cms_entradas e WHERE e.pagina_id = p.id AND e.slug = 'que-es-un-conflicto-de-interes-20250402');
SELECT p.id, 'Edicto - Luz Amanda Ruiz Castañeda', 'edicto-luz-amanda-ruiz-castaneda-20250401', 'La E.S.E Hospital San José del Guaviare informa que se realizará el pago de salarios y prestaciones sociales adeudados a la exservidora pública Luz Amanda Ruiz Castañeda. Fecha límite: 20 días a partir de esta publicación Lugar…', '<p>La E.S.E Hospital San José del Guaviare informa que se realizará el pago de salarios y prestaciones sociales adeudados a la exservidora pública Luz Amanda Ruiz Castañeda.<br><br><b>Fecha límite:</b> 20 días a partir de esta publicación<br><b>Lugar:</b> Ventanilla única, primer piso del hospital<br><b>Horario:</b> Lunes a viernes, 8:00 a.m. - 12:00 m. y 2:00 p.m. - 5:00 p.m.<br><b>Más información:</b> 3114600835<br><b>Correo:</b> contactenos@esehospitalguaviare.gov.co<br><br>¡Comparte esta información a quienes pueda interesarles!</p>
