SELECT p.id, 'Jornada de Salud Barrio Arazá', 'jornada-de-salud-barrio-araza-20250331', '¡Jornada de salud para el bienestar de todos! La E.S.E Hospital San José del Guaviare, en el marco de la Estrategia de Rehabilitación Psicosocial Comunitaria para la Convivencia y la No Repetición, invita a toda la comunidad a…', '<p>¡Jornada de salud para el bienestar de todos!<br>La E.S.E Hospital San José del Guaviare, en el marco de la Estrategia de Rehabilitación Psicosocial Comunitaria para la Convivencia y la No Repetición, invita a toda la comunidad a participar en esta jornada especial de salud.<br><br><b>Fecha:</b> 5 de abril<br><b>Hora:</b> 8:00 a.m. - 1:00 p.m.<br><b>Lugar:</b> Caseta comunal Arazá<br><br>Brindaremos atención y acompañamiento para promover el bienestar de nuestra comunidad.<br><b>¡Tu salud, nuestro compromiso!</b></p>
