SELECT p.id, 'Modificación de la Jornada Laboral por Semana Santa', 'modificacion-de-la-jornada-laboral-por-semana-santa-20250415', 'La E.S.E Hospital San José del Guaviare informa que, con motivo de la Semana Santa, el miércoles 16 de abril de 2025 se implementará una jornada laboral continua de 07:00 a.m. a 01:00 p.m. Esta medida busca adaptar las…', '<p>La E.S.E Hospital San José del Guaviare informa que, con motivo de la Semana Santa, el miércoles 16 de abril de 2025 se implementará una jornada laboral continua de 07:00 a.m. a 01:00 p.m. Esta medida busca adaptar las actividades institucionales a las necesidades de la temporada.<br>Se notifica a la comunidad que la atención al público será en ese mismo horario.</p>', 'noticia', 'publicada', 'E.S.E. Hospital San José del Guaviare', '2025-04-15 17:00:00', 0, 'esehospitalguaviare.gov.co/publicaciones/16'
