SELECT p.id, 'Segundo Edicto - Luz Amanda Ruiz Castañeda', 'segundo-edicto-luz-amanda-ruiz-castaneda-20250328', 'Teniendo en cuenta el fallecimiento de nuestra colaboradora Luz Amanda Ruiz Castañeda Q.E.P.D. y el proceso administrativo que se deriva de este hecho, solicito de su valiosa colaboración para publicar el segundo edicto en la…', '<p>Teniendo en cuenta el fallecimiento de nuestra colaboradora <b>Luz Amanda Ruiz Castañeda Q.E.P.D.</b> y el proceso administrativo que se deriva de este hecho, solicito de su valiosa colaboración para publicar el segundo edicto en la página web institucional, con el ánimo de dar a conocer a la comunidad en general el reconocimiento de salarios, prestaciones y demás emolumentos adeudados a la ex servidora pública.<br><br>La E.S.E. Hospital San José del Guaviare informa que se realizará el pago de salarios y prestaciones sociales adeudados a la exservidora pública Luz Amanda Ruiz Castañeda.<br>📅 <b>Fecha límite:</b> 30 días a partir de esta publicación<br>📍 <b>Lugar:</b> Ventanilla única, primer piso del hospital</p>', 'noticia', 'publicada', 'E.S.E. Hospital San José del Guaviare', '2025-03-28 17:00:00', 0, 'esehospitalguaviare.gov.co/publicaciones/16'
