SELECT p.id, 'Rendición de Cuentas', 'rendicion-de-cuentas-20250326', 'La E.S.E Hospital San José del Guaviare invita a la comunidad a participar en la Rendición de Cuentas de la Vigencia 2024 , un espacio de transparencia donde presentaremos nuestra gestión en salud. Fecha: 7 de abril de 2025 Hora…', '<p>La E.S.E Hospital San José del Guaviare invita a la comunidad a participar en la <b>Rendición de Cuentas de la Vigencia 2024</b>, un espacio de transparencia donde presentaremos nuestra gestión en salud.<br><b>Fecha:</b> 7 de abril de 2025<br><b>Hora:</b> 8:30 AM<br><b>Lugar:</b> Auditorio de la Contraloría Departamental del Guaviare<br><br>Además, te invitamos a visitar nuestro micrositio donde podrás conocer los puntos más importantes de esta rendición de cuentas.<br><a href="https://www.esehospitalguaviare.gov.co/rendicion-de-cuentas-24/" target="_blank" rel="noopener">Micrositio de Rendición de Cuentas</a></p>
