SELECT p.id, 'Día Mundial de la Tuberculosis', 'dia-mundial-de-la-tuberculosis-20250324', 'La tuberculosis tiene cura, pero es fundamental detectarla y tratarla a tiempo. Si tienes síntomas como tos persistente por más de 15 días, fiebre, sudoración nocturna o pérdida de peso, acude al hospital y busca atención médica…', '<p>La tuberculosis tiene cura, pero es fundamental detectarla y tratarla a tiempo. Si tienes síntomas como tos persistente por más de 15 días, fiebre, sudoración nocturna o pérdida de peso, acude al hospital y busca atención médica gratuita.<br>En la E.S.E. Hospital San José del Guaviare estamos comprometidos con la prevención, diagnóstico y tratamiento de esta enfermedad.<br><b>¡Juntos podemos frenar la tuberculosis!</b></p>
<p><a href="https://www.facebook.com/share/p/1BvnNcDcuN/" target="_blank" rel="noopener">Ver la publicación original en Facebook</a></p>', 'noticia', 'publicada', 'E.S.E. Hospital San José del Guaviare', '2025-03-24 17:00:00', 0, 'esehospitalguaviare.gov.co/publicaciones/16'
