SELECT p.id, 'Día Mundial del Agua', 'dia-mundial-del-agua-20250322', 'El agua es vida, salud y bienestar. En la E.S.E Hospital San José del Guaviare, reconocemos su importancia en la prevención de enfermedades y la atención segura de nuestros pacientes. Cuidarla es responsabilidad de todos. Hagamos…', '<p>El agua es vida, salud y bienestar. En la E.S.E Hospital San José del Guaviare, reconocemos su importancia en la prevención de enfermedades y la atención segura de nuestros pacientes.<br>Cuidarla es responsabilidad de todos. Hagamos un uso consciente y responsable de este recurso vital para garantizar un futuro saludable para nuestra comunidad.</p>
<p><a href="https://www.facebook.com/share/p/1BXpaXaThK/" target="_blank" rel="noopener">Ver la publicación original en Facebook</a></p>', 'noticia', 'publicada', 'E.S.E. Hospital San José del Guaviare', '2025-03-22 17:00:00', 0, 'esehospitalguaviare.gov.co/publicaciones/16'
  FROM cms_paginas p WHERE p.slug = 'noticias' AND NOT EXISTS (SELECT 1 FROM cms_entradas e WHERE e.pagina_id = p.id AND e.slug = 'dia-mundial-del-agua-20250322');
SELECT p.id, 'Homenaje Cumpleaños', 'homenaje-cumpleanos-20250321', '¡Celebramos 29 años al servicio de la salud en el Guaviare! Hoy conmemoramos un año más de compromiso, esfuerzo y dedicación en la E.S.E Hospital San José del Guaviare. Durante estos 29 años, hemos trabajado incansablemente para…', '<p>¡Celebramos 29 años al servicio de la salud en el Guaviare! Hoy conmemoramos un año más de compromiso, esfuerzo y dedicación en la E.S.E Hospital San José del Guaviare.<br>Durante estos 29 años, hemos trabajado incansablemente para brindar atención de calidad a nuestra comunidad, con un equipo humano que día a día da lo mejor de sí para cuidar la salud y el bienestar de todos.<br>Agradecemos a nuestro personal médico, asistencial y administrativo, quienes con su vocación y entrega hacen posible que sigamos creciendo y fortaleciendo nuestros servicios.<br>¡Gracias por ser parte de esta historia de salud y esperanza!<br><b>Tu Salud, Nuestro Compromiso</b></p>
<p><a href="https://www.facebook.com/share/p/18c4iq3YRC/" target="_blank" rel="noopener">Ver la publicación original en Facebook</a></p>', 'noticia', 'publicada', 'E.S.E. Hospital San José del Guaviare', '2025-03-21 17:00:00', 0, 'esehospitalguaviare.gov.co/publicaciones/16'
