SELECT p.id, 'Urgenciólogos de Bogotá', 'urgenciologos-de-bogota-20250307', '#AEstaHora recibimos en la E.S.E. Hospital San José del Guaviare la visita de un grupo de urgenciólogos de Bogotá, especializados en clínicas y hospitales de III y IV nivel. Gracias a su conocimiento y experiencia, abordamos…', '<p>#AEstaHora recibimos en la E.S.E. Hospital San José del Guaviare la visita de un grupo de urgenciólogos de Bogotá, especializados en clínicas y hospitales de III y IV nivel.<br>Gracias a su conocimiento y experiencia, abordamos nuevas estrategias para optimizar la atención en el servicio de urgencias, con el objetivo de brindar una respuesta más rápida y eficiente a nuestra comunidad.<br>¡Seguimos trabajando por una salud de calidad para todos!</p>
