SELECT p.id, 'Homenaje Día de la Mujer', 'homenaje-dia-de-la-mujer-20250307', 'Celebramos a las mujeres que cuidan la salud del Guaviare. Con gran éxito, la E.S.E. Hospital San José del Guaviare, bajo la dirección del gerente Dr. Germán Amézquita, celebró el Día de la Mujer, rindiendo homenaje a todas las…', '<p>Celebramos a las mujeres que cuidan la salud del Guaviare.<br>Con gran éxito, la E.S.E. Hospital San José del Guaviare, bajo la dirección del gerente Dr. Germán Amézquita, celebró el Día de la Mujer, rindiendo homenaje a todas las mujeres que hacen parte de nuestra institución.<br><br>Cada día, su compromiso y dedicación son fundamentales para brindar una atención de calidad y mejorar la salud de nuestra comunidad.<br>¡Gracias por su entrega y vocación!</p>
<p><a href="https://www.facebook.com/share/p/17od12CE5k/" target="_blank" rel="noopener">Ver la publicación original en Facebook</a></p>', 'noticia', 'publicada', 'E.S.E. Hospital San José del Guaviare', '2025-03-07 17:00:00', 0, 'esehospitalguaviare.gov.co/publicaciones/16'
