SELECT p.id, 'Plan de Gestión 2024 – 2027', 'plan-de-gestion-2024-2027-20250307', 'El Plan de Gestión 2024 - 2027 "Tu Salud, Nuestro Compromiso" del Hospital San José del Guaviare, presentado por el Dr. Germán Amézquita y su equipo de trabajo, ha sido aprobado por la Junta Directiva. Este plan nos permitirá…', '<p>El Plan de Gestión 2024 - 2027 <b>"Tu Salud, Nuestro Compromiso"</b> del Hospital San José del Guaviare,<br>presentado por el Dr. Germán Amézquita y su equipo de trabajo, ha sido aprobado por la Junta Directiva.<br><br>Este plan nos permitirá implementar nuevas estrategias para fortalecer la salud en el Guaviare,<br>garantizando servicios de calidad para toda la comunidad.<br><br>¡Seguimos trabajando por el bienestar de todos!</p>
<p><a href="https://www.facebook.com/share/p/1A9qY2riAi/" target="_blank" rel="noopener">Ver la publicación original en Facebook</a></p>', 'noticia', 'publicada', 'E.S.E. Hospital San José del Guaviare', '2025-03-07 17:00:00', 0, 'esehospitalguaviare.gov.co/publicaciones/16'
