SELECT p.id, 'Celebración Día de la Mujer', 'celebracion-dia-de-la-mujer-20250304', '¡Mujer, este día es para ti! Celebración Día de la Mujer. Porque eres inspiración, fuerza y vida, la E.S.E. Hospital San José del Guaviare, en cabeza de nuestro gerente Germán Amézquita, tiene el honor de invitarte a una…', '<p>¡Mujer, este día es para ti! Celebración Día de la Mujer.<br>Porque eres inspiración, fuerza y vida, la E.S.E. Hospital San José del Guaviare, en cabeza de nuestro gerente Germán Amézquita, tiene el honor de invitarte a una celebración especial en homenaje a ti.<br><br><b>Fecha:</b> Viernes 7 de marzo de 2025<br><b>Hora:</b> 8:00 a. m.<br><b>Lugar:</b> Auditorio del Hospital San José del Guaviare<br><br>Será un encuentro lleno de gratitud, reconocimiento y sorpresas. ¡No te lo puedes perder!</p>
<p><a href="https://www.facebook.com/share/p/1DSDTqw6W5/" target="_blank" rel="noopener">Ver la publicación original en Facebook</a></p>', 'noticia', 'publicada', 'E.S.E. Hospital San José del Guaviare', '2025-03-04 17:00:00', 0, 'esehospitalguaviare.gov.co/publicaciones/16'
  FROM cms_paginas p WHERE p.slug = 'noticias' AND NOT EXISTS (SELECT 1 FROM cms_entradas e WHERE e.pagina_id = p.id AND e.slug = 'celebracion-dia-de-la-mujer-20250304');
SELECT p.id, 'Donatón', 'donaton-20250303', '¡Tu solidaridad hace la diferencia! No necesitas un día especial para apoyar una noble causa. La E.S.E. Hospital San José del Guaviare te invita a unirte a nuestra Gran Donatón para dotar nuestro Banco de Ayuda. ¿Qué puedes…', '<p>¡Tu solidaridad hace la diferencia!<br>No necesitas un día especial para apoyar una noble causa. La E.S.E. Hospital San José del Guaviare te invita a unirte a nuestra <b>Gran Donatón</b> para dotar nuestro Banco de Ayuda.<br><br><b>¿Qué puedes donar?</b><br>- Ropa para bebés, niños, hombres y mujeres.<br>- Elementos de aseo esenciales para nuestros pacientes sin red de apoyo.<br><br>Tu generosidad transforma vidas. Súmate y ayúdanos a brindar esperanza a quienes más lo necesitan.<br>Acércate al hospital y deja tu donación en la oficina de trabajo social.<br><br><b>¡Juntos hacemos la diferencia!</b></p>
<p><a href="https://www.facebook.com/share/p/1FApMsq4kA/" target="_blank" rel="noopener">Ver la publicación original en Facebook</a></p>', 'noticia', 'publicada', 'E.S.E. Hospital San José del Guaviare', '2025-03-03 17:00:00', 0, 'esehospitalguaviare.gov.co/publicaciones/16'
  FROM cms_paginas p WHERE p.slug = 'noticias' AND NOT EXISTS (SELECT 1 FROM cms_entradas e WHERE e.pagina_id = p.id AND e.slug = 'donaton-20250303');
SELECT p.id, 'Día de la Mujer', 'dia-de-la-mujer-20250303', 'En el marco de la celebración del Día de la Mujer, la E.S.E. Hospital San José del Guaviare rinde un homenaje especial a las mujeres profesionales de la salud, quienes han entregado su vida, tiempo y vocación al bienestar de los…', '<p>En el marco de la celebración del Día de la Mujer, la E.S.E. Hospital San José del Guaviare rinde un homenaje especial a las mujeres profesionales de la salud,<br>quienes han entregado su vida, tiempo y vocación al bienestar de los guaviarenses.<br>¡Gracias por su incansable labor y por ser un pilar fundamental en nuestra comunidad!</p>
<p><a href="https://www.facebook.com/share/p/16QmMDsr4z/" target="_blank" rel="noopener">Ver la publicación original en Facebook</a></p>', 'noticia', 'publicada', 'E.S.E. Hospital San José del Guaviare', '2025-03-03 17:00:00', 0, 'esehospitalguaviare.gov.co/publicaciones/16'
