SELECT p.id, 'Cirugías Urológicas', 'cirugias-urologicas-20250228', '¡Avanzamos en salud para nuestra comunidad! En la E.S.E. Hospital San José del Guaviare, seguimos innovando en nuestras jornadas de salud para brindar una atención de calidad. Ahora, los pacientes de San José del Guaviare y sus…', '<p>¡Avanzamos en salud para nuestra comunidad!<br>En la E.S.E. Hospital San José del Guaviare, seguimos innovando en nuestras jornadas de salud para brindar una atención de calidad.<br>Ahora, los pacientes de San José del Guaviare y sus alrededores pueden acceder a cirugías urológicas mínimamente invasivas sin necesidad de ser remitidos a otros centros.<br>Contamos con tecnología de punta, incluyendo una torre de endoscopia con cámara HD, resectoscopio y energía especializada para realizar estos procedimientos con mayor precisión y seguridad.<br><br>Menos tiempo de recuperación.<br>Menos riesgos.<br>Atención de calidad, cerca de ti.<br>Tu salud, nuestra prioridad. ¡Seguimos avanzando para ti!</p>
<p><a href="https://www.facebook.com/share/p/1945jywewr/" target="_blank" rel="noopener">Ver la publicación original en Facebook</a></p>', 'noticia', 'publicada', 'E.S.E. Hospital San José del Guaviare', '2025-02-28 17:00:00', 0, 'esehospitalguaviare.gov.co/publicaciones/16'
