SELECT p.id, 'Hoy es el Día Mundial de las Enfermedades Huérfanas', 'hoy-es-el-dia-mundial-de-las-enfermedades-huerfanas-20250228', '+300 millones de personas en el mundo viven con una enfermedad rara. En Colombia, hay más de 2.000 enfermedades huérfanas identificadas, muchas de ellas sin tratamiento o con acceso limitado a la atención. Diagnóstico tardío…', '<p>+300 millones de personas en el mundo viven con una enfermedad rara. En Colombia, hay más de 2.000 enfermedades huérfanas identificadas, muchas de ellas sin tratamiento o con acceso limitado a la atención.<br>Diagnóstico tardío, tratamientos costosos y falta de investigación son algunos de los desafíos que enfrentan los pacientes y sus familias.<br>Hagamos visible lo invisible. Hoy es el día para alzar la voz por quienes luchan cada día con una enfermedad rara.</p>
<p><a href="https://www.facebook.com/share/p/1C53F7GunE/" target="_blank" rel="noopener">Ver la publicación original en Facebook</a></p>', 'noticia', 'publicada', 'E.S.E. Hospital San José del Guaviare', '2025-02-28 17:00:00', 0, 'esehospitalguaviare.gov.co/publicaciones/16'
