SELECT p.id, 'Jornada de Embellecimiento', 'jornada-de-embellecimiento-20250224', '¡Cuidamos nuestro hospital para brindarte lo mejor! Nuestro equipo de la E.S.E. Hospital San José del Guaviare realiza una Jornada de Embellecimiento, mejorando las instalaciones para ofrecer un espacio más agradable y digno para…', '<p>¡Cuidamos nuestro hospital para brindarte lo mejor!<br>Nuestro equipo de la E.S.E. Hospital San José del Guaviare realiza una Jornada de Embellecimiento, mejorando las instalaciones para ofrecer un espacio más agradable y digno para todos. Porque tu bienestar empieza desde el primer momento en que cruzas nuestras puertas.<br>Agradecemos a nuestros funcionarios por esta excelente labor</p>
<p><a href="https://www.facebook.com/share/p/196KidpWkD/" target="_blank" rel="noopener">Ver la publicación original en Facebook</a></p>', 'noticia', 'publicada', 'E.S.E. Hospital San José del Guaviare', '2025-02-24 17:00:00', 0, 'esehospitalguaviare.gov.co/publicaciones/16'
