SELECT p.id, 'Servicio de Electroencefalograma', 'servicio-de-electroencefalograma-20250220', 'En la ESE Hospital San José del Guaviare, contamos con el servicio de electroencefalograma (EEG), un estudio fundamental para detectar epilepsia, trastornos del sueño, secuelas de traumatismos craneoencefálicos y otras…', '<p>En la ESE Hospital San José del Guaviare, contamos con el servicio de electroencefalograma (EEG), un estudio fundamental para detectar epilepsia, trastornos del sueño, secuelas de traumatismos craneoencefálicos y otras alteraciones neurológicas.<br>Por eso, realizamos una jornada especial de toma de electroencefalogramas, facilitando el acceso a este examen que puede ayudarte a recibir un diagnóstico oportuno y el tratamiento adecuado.<br>No ignores los síntomas, tu salud es lo más importante. Acércate y agenda tu examen.</p>
<p><a href="https://www.facebook.com/share/p/1BPrDEHaNC/" target="_blank" rel="noopener">Ver la publicación original en Facebook</a></p>', 'noticia', 'publicada', 'E.S.E. Hospital San José del Guaviare', '2025-02-20 17:00:00', 0, 'esehospitalguaviare.gov.co/publicaciones/16'
