SELECT p.id, 'Capacitación en Inteligencia Artificial', 'capacitacion-en-inteligencia-artificial-20250219', 'La E.S.E Hospital San José del Guaviare está fortaleciendo su equipo con una capacitación de vanguardia en transformación digital e inteligencia artificial (IA). Esta iniciativa busca potenciar las competencias laborales de un…', '<p>La E.S.E Hospital San José del Guaviare está fortaleciendo su equipo con una capacitación de vanguardia en transformación digital e inteligencia artificial (IA). Esta iniciativa busca potenciar las competencias laborales de un servidor 4.0, preparándolos para los desafíos del futuro y elevando la productividad del hospital.<br>¡Un paso adelante para brindar la mejor atención en salud!</p>
<p><a href="https://www.facebook.com/hospitalsanjosedelguaviare/posts/pfbid02H3stz43oZEtm4btR4q6tGGxKYA5mTc7vsBzoAsfiDscC9rEN64sQwq1N6go6EsnTl" target="_blank" rel="noopener">Ver la publicación original en Facebook</a></p>', 'noticia', 'publicada', 'E.S.E. Hospital San José del Guaviare', '2025-02-19 17:00:00', 0, 'esehospitalguaviare.gov.co/publicaciones/16'
