SELECT p.id, 'Condolencias', 'condolencias-20250213', 'La E.S.E. Hospital San José del Guaviare, en cabeza de su gerente Germán Amezquita, lamenta profundamente el fallecimiento de Leiver Andrés Preciado, quien hizo parte de la institución como auxiliar de enfermería, destacándose…', '<p>La E.S.E. Hospital San José del Guaviare, en cabeza de su gerente Germán Amezquita, lamenta profundamente el fallecimiento de Leiver Andrés Preciado, quien hizo parte de la institución como auxiliar de enfermería, destacándose por su compromiso y vocación de servicio, especialmente durante la pandemia.<br>Expresamos nuestras más sinceras condolencias a su familia, amigos y seres queridos en este difícil momento. Su entrega y dedicación serán siempre recordadas con gratitud y respeto.<br>Que su alma descanse en paz.</p>
<p><a href="https://www.facebook.com/share/p/14sAdDeASu/" target="_blank" rel="noopener">Ver la publicación original en Facebook</a></p>', 'noticia', 'publicada', 'E.S.E. Hospital San José del Guaviare', '2025-02-13 17:00:00', 0, 'esehospitalguaviare.gov.co/publicaciones/16'
