SELECT p.id, 'Día Internacional del Condón', 'dia-internacional-del-condon-20250213', 'El E.S.E Hospital San José del Guaviare te invita a conocer información relevante sobre esta fecha conmemorativa, que busca concientizar sobre la importancia del uso del condón como método de prevención de infecciones de…', '<p>El E.S.E Hospital San José del Guaviare te invita a conocer información relevante sobre esta fecha conmemorativa, que busca concientizar sobre la importancia del uso del condón como método de prevención de infecciones de transmisión sexual (ITS) y embarazos no planificados.<br>Recordemos que el condón es una herramienta segura, accesible y eficaz para el cuidado de la salud sexual. ¡Infórmate, protégete y promueve el autocuidado!</p>
<p><a href="https://www.facebook.com/share/p/1CXpJKDDiU/" target="_blank" rel="noopener">Ver la publicación original en Facebook</a></p>', 'noticia', 'publicada', 'E.S.E. Hospital San José del Guaviare', '2025-02-13 17:00:00', 0, 'esehospitalguaviare.gov.co/publicaciones/16'
