SELECT p.id, 'Médicos de Servicio Social Obligatorio', 'medicos-de-servicio-social-obligatorio-20250212', 'La ESE Hospital San José del Guaviare, bajo el liderazgo de nuestro gerente Germán Amézquita, se enorgullece en recibir al nuevo grupo de médicos de servicio social obligatorio. Con alegría y orgullo, damos la bienvenida a estos…', '<p>La ESE Hospital San José del Guaviare, bajo el liderazgo de nuestro gerente Germán Amézquita, se enorgullece en recibir al nuevo grupo de médicos de servicio social obligatorio. Con alegría y orgullo, damos la bienvenida a estos talentosos doctores, hijos del Guaviare, que fortalecerán nuestro equipo de trabajo y velarán por la salud de nuestra comunidad.</p>
<p><a href="https://www.facebook.com/share/p/195BwT34ET/" target="_blank" rel="noopener">Ver la publicación original en Facebook</a></p>', 'noticia', 'publicada', 'E.S.E. Hospital San José del Guaviare', '2025-02-12 17:00:00', 0, 'esehospitalguaviare.gov.co/publicaciones/16'
