SELECT p.id, 'Jornada de Radiología Calamar Y Retorno', 'jornada-de-radiologia-calamar-y-retorno-20250211', 'La E.S.E. Hospital San José del Guaviare sigue acercando sus servicios a la comunidad. Esta vez, llevamos una jornada de salud a los municipios de El Retorno y Calamar, donde un médico especialista en radiología e imágenes…', '<p>La E.S.E. Hospital San José del Guaviare sigue acercando sus servicios a la comunidad. Esta vez, llevamos una jornada de salud a los municipios de El Retorno y Calamar, donde un médico especialista en radiología e imágenes diagnósticas realizó ecografías de abdomen, vías urinarias, tejidos blandos y más.<br>Además, en el hospital se llevó a cabo una jornada de biopsias de tiroides, una estrategia clave para la detección temprana del cáncer de tiroides y la prevención de futuras complicaciones.<br>Nuestro compromiso es garantizar una atención de calidad en las zonas rurales del departamento. ¡Seguimos trabajando por tu bienestar!</p>
<p><a href="https://www.facebook.com/share/p/164dK5wniY/" target="_blank" rel="noopener">Ver la publicación original en Facebook</a></p>', 'noticia', 'publicada', 'E.S.E. Hospital San José del Guaviare', '2025-02-11 17:00:00', 0, 'esehospitalguaviare.gov.co/publicaciones/16'
  FROM cms_paginas p WHERE p.slug = 'noticias' AND NOT EXISTS (SELECT 1 FROM cms_entradas e WHERE e.pagina_id = p.id AND e.slug = 'jornada-de-radiologia-calamar-y-retorno-20250211');
SELECT p.id, '¡Más salud para el Guaviare!', 'mas-salud-para-el-guaviare-20250209', 'La ESE Hospital San José del Guaviare Este fin de semana realizó Jornada de Gastroenterología, donde se brindó atención especializada a nuestros pacientes. Endoscopias de vias digestivas altas Toma de biopsias Colonoscopias…', '<p>La ESE Hospital San José del Guaviare Este fin de semana realizó Jornada de Gastroenterología, donde se brindó atención especializada a nuestros pacientes.<br>Endoscopias de vias digestivas altas<br>Toma de biopsias<br>Colonoscopias<br>Valoraciones médicas especializadas<br>Continuaremos trabajando para brindar más servicios de salud. ¡Tu bienestar es nuestra prioridad!</p>
