SELECT p.id, 'Ayuda Urgente', 'ayuda-urgente-20250207', '¡Ayúdanos a encontrar a su familia! La ESE Hospital San José del Guaviare solicita el apoyo de la comunidad para localizar a familiares o amigos de Jose Angel Arias Guerrero y Marco Aurelio Yaruro Pallares quienes se encuentran…', '<p><b>¡Ayúdanos a encontrar a su familia!</b><br>La ESE Hospital San José del Guaviare solicita el apoyo de la comunidad para localizar a familiares o amigos de <b>Jose Angel Arias Guerrero y Marco Aurelio Yaruro Pallares</b> quienes se encuentran en La ESE Hospital San José del Guaviare.<br>Si tienes información sobre su paradero o familiares, acércate al área de Trabajo Social del hospital o comunícate al <b>321 346 3293</b>.<br>¡Tu ayuda es crucial!</p>
<p><a href="https://www.facebook.com/share/p/15eKvHhX6N/" target="_blank" rel="noopener">Ver la publicación original en Facebook</a></p>', 'noticia', 'publicada', 'E.S.E. Hospital San José del Guaviare', '2025-02-07 17:00:00', 0, 'esehospitalguaviare.gov.co/publicaciones/16'
