SELECT p.id, '¡Así se Vivió la Feria de Vivienda 2025 en la E.S.E Hospital San José del Guaviare!', 'asi-se-vivio-la-feria-de-vivienda-2025-en-la-e-s-e-hospital-san-jose-d-20250205', 'Con una gran asistencia, nuestros servidores públicos y contratistas participaron en esta exitosa jornada, donde recibieron información clave sobre los beneficios y oportunidades en vivienda, gracias a la alianza con el Fondo…', '<p>Con una gran asistencia, nuestros servidores públicos y contratistas participaron en esta exitosa jornada, donde recibieron información clave sobre los beneficios y oportunidades en vivienda, gracias a la alianza con el Fondo Nacional del Ahorro, COMCAJA, el Círculo de Viajes Universal SAS - CVU, Dica Constructora SAS, Coring SAS y Pelícano Ltda.<br>Además, gracias al Comité de Bienestar, premiamos a nuestros asistentes, haciendo de este evento una experiencia aún más especial.<br>¡Seguimos trabajando por el bienestar de quienes día a día cuidan de nuestra comunidad!</p>
<p><a href="https://www.facebook.com/share/p/18dzetLkHD/" target="_blank" rel="noopener">Ver la publicación original en Facebook</a></p>', 'noticia', 'publicada', 'E.S.E. Hospital San José del Guaviare', '2025-02-05 17:00:00', 0, 'esehospitalguaviare.gov.co/publicaciones/16'
