SELECT p.id, '¡Buenas Noticias para la Salud en el Guaviare!', 'buenas-noticias-para-la-salud-en-el-guaviare-20250204', 'Los gerentes de la ESE Hospital de Segundo Nivel Germán Amézquita y la ESE de Primer Nivel han Acordado la firma de un convenio interadministrativo para fortalecer la red pública de salud. Esta alianza permitirá mejorar la…', '<p>Los gerentes de la ESE Hospital de Segundo Nivel <b>Germán Amézquita</b> y la ESE de Primer Nivel han Acordado la firma de un convenio interadministrativo para fortalecer la red pública de salud.<br>Esta alianza permitirá mejorar la atención, ampliar la cobertura y facilitar el acceso a exámenes especializados y especialistas en los municipios. ¡Un gran paso para el bienestar de todos los guaviarenses!</p>
<p><a href="https://www.facebook.com/share/p/1A4WmbzJoj/" target="_blank" rel="noopener">Ver la publicación original en Facebook</a></p>', 'noticia', 'publicada', 'E.S.E. Hospital San José del Guaviare', '2025-02-04 17:00:00', 0, 'esehospitalguaviare.gov.co/publicaciones/16'
