SELECT p.id, 'Día Mundia de la Lucha Contra el Cáncer', 'dia-mundia-de-la-lucha-contra-el-cancer-20250204', 'ESE Hospital San José del Guaviare Hoy, en el Día Mundial de la Lucha contra el Cáncer, te invita a tomar acción para tu salud. La prevención y el diagnóstico temprano son clave para salvar vidas . Realízate los exámenes…', '<p>ESE Hospital San José del Guaviare Hoy, en el Día Mundial de la Lucha contra el Cáncer, te invita a tomar acción para tu salud. <b>La prevención y el diagnóstico temprano son clave para salvar vidas</b>.<br>Realízate los exámenes necesarios y no dejes pasar ningún síntoma. Si obtienes un resultado positivo, nuestro equipo está listo para acompañarte en tu tratamiento y brindarte el apoyo que necesitas.<br>Línea de WhatsApp: 310 876 3343 (Reportes de Patologías) O acercándote personalmente al Área de Patología de: La ESE Hospital San José del Guaviare.<br>Horario de atención: lunes a viernes 7:00 am<br>12:00 pm 2:00 pm - 5:00 pm<br><b>La detección temprana salva vidas. ¡Contamos contigo en la lucha!</b></p>
<p><a href="https://www.facebook.com/share/p/155auEnnaV/" target="_blank" rel="noopener">Ver la publicación original en Facebook</a></p>', 'noticia', 'publicada', 'E.S.E. Hospital San José del Guaviare', '2025-02-04 17:00:00', 0, 'esehospitalguaviare.gov.co/publicaciones/16'
