SELECT p.id, '¡Felicitaciones al Doctor Germán Amézquita!', 'felicitaciones-al-doctor-german-amezquita-20250127', 'El equipo de trabajo de la E.S.E. Hospital San José del Guaviare expresa sus más sinceras felicitaciones al Dr. Germán Amézquita por su posesión como gerente de nuestra institución. Estamos seguros de que su liderazgo, compromiso…', '<p>El equipo de trabajo de la E.S.E. Hospital San José del Guaviare expresa sus más sinceras felicitaciones al Dr. Germán Amézquita por su posesión como gerente de nuestra institución.<br>Estamos seguros de que su liderazgo, compromiso y visión serán fundamentales para seguir fortaleciendo la atención en salud y el bienestar de nuestra comunidad.<br>¡Éxitos en esta nueva etapa, doctor!</p>
<p><a href="https://www.facebook.com/share/p/1HRWeCfZNC/" target="_blank" rel="noopener">Ver la publicación original en Facebook</a></p>', 'noticia', 'publicada', 'E.S.E. Hospital San José del Guaviare', '2025-01-27 17:00:00', 0, 'esehospitalguaviare.gov.co/publicaciones/16'
