SELECT p.id, '¡Construyamos juntos un futuro de paz!', 'construyamos-juntos-un-futuro-de-paz-20250124', 'La E.S.E Hospital San José del Guaviare te invita a ser parte de nuestra Estrategia de Rehabilitación Psicosocial Comunitaria, una iniciativa que fortalece el tejido social y fomenta la convivencia pacífica. ¿A quién está…', '<p>La E.S.E Hospital San José del Guaviare te invita a ser parte de nuestra Estrategia de Rehabilitación Psicosocial Comunitaria, una iniciativa que fortalece el tejido social y fomenta la convivencia pacífica.<br>¿A quién está dirigida?<br>Víctimas del conflicto armado<br>Excombatientes en reincorporación<br>Comunidades locales<br>Líderes sociales<br>Únete a este esfuerzo colectivo y contribuye a transformar vidas mientras sembramos esperanza y reconciliación. ¡Juntos podemos construir un territorio más unido y en paz!<br>Te esperamos para ser parte de este gran cambio.</p>
<p><a href="https://www.facebook.com/share/p/165Mw4hhde/" target="_blank" rel="noopener">Ver la publicación original en Facebook</a></p>', 'noticia', 'publicada', 'E.S.E. Hospital San José del Guaviare', '2025-01-24 17:00:00', 0, 'esehospitalguaviare.gov.co/publicaciones/16'
  FROM cms_paginas p WHERE p.slug = 'noticias' AND NOT EXISTS (SELECT 1 FROM cms_entradas e WHERE e.pagina_id = p.id AND e.slug = 'construyamos-juntos-un-futuro-de-paz-20250124');
SELECT p.id, 'Unidos por la excelencia en gestión pública', 'unidos-por-la-excelencia-en-gestion-publica-20250121', 'La E.S.E Hospital San José del Guaviare y la Gobernación de Guaviare sumaron esfuerzos mediante una articulación interinstitucional para fortalecer el conocimiento y la implementación del Modelo Integrado de Planeación y Gestión…', '<p>La <b>E.S.E Hospital San José del Guaviare</b> y la <b>Gobernación de Guaviare</b> sumaron esfuerzos mediante una articulación interinstitucional para fortalecer el conocimiento y la implementación del Modelo Integrado de Planeación y Gestión (MIPG) y la planeación estratégica.<br><b>¿El objetivo?</b><br>Mejorar las capacidades institucionales y desarrollar acciones conjuntas que impacten positivamente la gestión pública, beneficiando a toda nuestra comunidad.<br>Juntos construimos un futuro mejor para el Guaviare.</p>
<p><a href="https://www.facebook.com/share/p/1BEDrP5dy4/" target="_blank" rel="noopener">Ver la publicación original en Facebook</a></p>', 'noticia', 'publicada', 'E.S.E. Hospital San José del Guaviare', '2025-01-21 17:00:00', 0, 'esehospitalguaviare.gov.co/publicaciones/16'
