SELECT p.id, '¡Gran Final del 2do Campeonato de Fútbol 7 Empresarial 2024 en San José del Guaviare!', 'gran-final-del-2do-campeonato-de-futbol-7-empresarial-2024-en-san-jose-20250121', 'El pasado 18 de enero, vivimos una emocionante final entre los equipos que demostraron talento, pasión y espíritu deportivo. El equipo Gremio Salud Guaviare, conformado en su mayoría por trabajadores del Hospital Departamental…', '<p>El pasado 18 de enero, vivimos una emocionante final entre los equipos que demostraron talento, pasión y espíritu deportivo. El equipo Gremio Salud Guaviare, conformado en su mayoría por trabajadores del Hospital Departamental, se coronó subcampeón, manteniendo su liderazgo en este campeonato tras haber sido los campeones en la edición anterior.<br>Agradecemos a todos los participantes y a quienes apoyan estas actividades deportivas que unen a nuestra comunidad. ¡El deporte sigue siendo el puente para la amistad, el esfuerzo y la sana competencia!</p>
<p><a href="https://www.facebook.com/share/p/1XGd6nzoCo/" target="_blank" rel="noopener">Ver la publicación original en Facebook</a></p>', 'noticia', 'publicada', 'E.S.E. Hospital San José del Guaviare', '2025-01-21 17:00:00', 0, 'esehospitalguaviare.gov.co/publicaciones/16'
