SELECT p.id, 'Salidas Ecologicas', 'salidas-ecologicas-20240708', 'Pensando siempre en el bienestar y la salud mental de nuestros Funcionarios y Colaboradores, la ESE Hospital San José del Guaviare en dirección de la Gerente de la entidad Oveida Parra Novoa y el Comité de Bienestar Social e…', '<p>Pensando siempre en el bienestar y la salud mental de nuestros Funcionarios y Colaboradores, la ESE Hospital San José del Guaviare en dirección de la Gerente de la entidad Oveida Parra Novoa y el Comité de Bienestar Social e Incentivos; inició el pasado viernes 05 de julio las salidas ecológicas al sitio Turístico Gallito de Roca.</p>', 'noticia', 'publicada', 'E.S.E. Hospital San José del Guaviare', '2024-07-08 17:00:00', 0, 'esehospitalguaviare.gov.co/publicaciones/16'
