SELECT p.id, 'Siembra De Arboles', 'siembra-de-arboles-20240524', 'Desde la ESE Hospital San José del Guaviare, estamos comprometidos con la protección y conservación del medio ambiente como parte de nuestras iniciativas de responsabilidad social y ambiental. Por lo anterior, en conmemoración…', '<p>Desde la ESE Hospital San José del Guaviare, estamos comprometidos con la protección y conservación del medio ambiente como parte de nuestras iniciativas de responsabilidad social y ambiental.</p>
