SELECT p.id, 'Nuevo Ecografo', 'nuevo-ecografo-20240429', 'La ESE Hospital San José del Guaviare, recibe la donación de un ecógrafo gracias a los esfuerzos realizados por el Ministerio de Salud y Protección Social ante el Gobierno de Japón. Este equipo biomédico, aportará al mejoramiento…', '<p>La ESE Hospital San José del Guaviare, recibe la donación de un ecógrafo gracias a los esfuerzos realizados por el Ministerio de Salud y Protección Social ante el Gobierno de Japón. Este equipo biomédico, aportará al mejoramiento de la atención de los pacientes que ingresan a nuestras instalaciones y facilitará el diagnóstico y seguimiento oportuno.</p>', 'noticia', 'publicada', 'E.S.E. Hospital San José del Guaviare', '2024-04-29 17:00:00', 0, 'esehospitalguaviare.gov.co/publicaciones/16'
