SELECT p.id, '¡Ayúdanos a encontrar su familia!', 'ayudanos-a-encontrar-su-familia-20240130', 'La ESE Hospital San José del Guaviare busca los familiares de María Herminia Ángel Quiroga, Erasmo Bermúdez, Rito Antonio Umaña, Jairo Eduardo Ramírez Rodríguez y Hernando Pineda quienes se encuentran internados en las…', '<p>La ESE Hospital San José del Guaviare busca los familiares de María Herminia Ángel Quiroga, Erasmo Bermúdez, Rito Antonio Umaña, Jairo Eduardo Ramírez Rodríguez y Hernando Pineda quienes se encuentran internados en las instalaciones de la entidad.</p>', 'noticia', 'publicada', 'E.S.E. Hospital San José del Guaviare', '2024-01-30 17:00:00', 0, 'esehospitalguaviare.gov.co/publicaciones/16'
