SELECT p.id, '¡Ahora es realidad la construcción de la nueva ESE Hospital San José del Guaviare!', 'ahora-es-realidad-la-construccion-de-la-nueva-ese-hospital-san-jose-de-20231229', 'La Gerente de la ESE Hospital San José del Guaviare; Oveida Parra Novoa presidió de manera oficial, la bendición y colocación de la primera piedra del Proyecto de Remodelación Ampliación y Construcción de la entidad, acto que…', '<p>La Gerente de la ESE Hospital San José del Guaviare; Oveida Parra Novoa presidió de manera oficial, la bendición y colocación de la primera piedra del Proyecto de Remodelación Ampliación y Construcción de la entidad, acto que simbolizó el inicio de la construcción de este transcendental y anhelado proyecto que, inició aproximadamente hace 6 años con el apoyo del ex gobernador del Guaviare Heydeer Yovanny Palacio Salazar, el representante a la Cámara Alexander Quevedo, y el actual gobernador del departamento Yeison Ferney Rojas Martínez.</p>', 'noticia', 'publicada', 'E.S.E. Hospital San José del Guaviare', '2023-12-29 17:00:00', 0, 'esehospitalguaviare.gov.co/publicaciones/16'
  FROM cms_paginas p WHERE p.slug = 'noticias' AND NOT EXISTS (SELECT 1 FROM cms_entradas e WHERE e.pagina_id = p.id AND e.slug = 'ahora-es-realidad-la-construccion-de-la-nueva-ese-hospital-san-jose-de-20231229');
