SELECT p.id, 'Celebración Día del Medico', 'celebracion-dia-del-medico-20231209', 'En conmemoración del Día del Médico la gerente de la ESE Hospital San José del Guaviare, Oveida Parra Novoa y el Comité de Bienestar Social e Incentivos, realizó una cena en agradecimiento a todos aquellos galenos que, con…', '<p>En conmemoración del Día del Médico la gerente de la ESE Hospital San José del Guaviare, Oveida Parra Novoa y el Comité de Bienestar Social e Incentivos, realizó una cena en agradecimiento a todos aquellos galenos que, con vocación y dedicación han abrazado la noble profesión de la medicina en una lucha continua por preservar la salud y la vida en cada consulta, diagnóstico y tratamiento.</p>
<p>Asimismo, la Gerente de la Entidad otorgó un merecido reconocimiento a los doctores: Rubén Dario Grass Paternina, Oscar Darío Ariza Montoya, Diego Armando Arias Rojas, Miguel Ángel Cerón Molina, Alfredo Sequi Ahcar Bedoya, Rafael Ángel Donado Vega, Henry Alexander Solaque Ramírez, Javier Enrique Pertuz, Rodolfo Antonio Aun Dau, Efraín Ardila y José Manuel Santoyo Ardila por haber ejercido su magna profesión por más de diez años en nuestra institución con ejemplar y generosa dedicación.</p>', 'noticia', 'publicada', 'E.S.E. Hospital San José del Guaviare', '2023-12-09 17:00:00', 0, 'esehospitalguaviare.gov.co/publicaciones/16'
  FROM cms_paginas p WHERE p.slug = 'noticias' AND NOT EXISTS (SELECT 1 FROM cms_entradas e WHERE e.pagina_id = p.id AND e.slug = 'celebracion-dia-del-medico-20231209');
